package com.focusflow.api.service; import com.focusflow.api.dto.ApiDtos.*; import com.focusflow.api.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*; @Service public class SyncService {final TaskRepository tasks;final CategoryRepository cats;final TaskService taskService;final CategoryService categoryService;public SyncService(TaskRepository t,CategoryRepository c,TaskService ts,CategoryService cs){tasks=t;cats=c;taskService=ts;categoryService=cs;} @Transactional public SyncResponse save(SyncRequest r,String user){tasks.deleteByUserId(user);cats.deleteByUserId(user);var categories=(r.categories()==null?List.<CategoryRequest>of():r.categories()).stream().map(x->categoryService.create(x,user)).toList();var taskList=(r.tasks()==null?List.<TaskRequest>of():r.tasks()).stream().map(x->taskService.create(x,user)).toList();return new SyncResponse(taskList,categories);} public SyncResponse load(String user){return new SyncResponse(taskService.all(user),categoryService.all(user));} }
